1	package credit
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"os"
10		"path/filepath"
11	)
12	
13	// recordVersion 是当前记录文件格式版本。
14	const recordVersion = 1
15	
16	// fileData 是记录文件的磁盘格式。
17	type fileData struct {
18		Version       int            `json:"version"`
19		Courses       []*Course      `json:"courses"`
20		Students      []*Student     `json:"students"`
21		Requirements  []*Requirement `json:"requirements"`
22		Enrollments   []*Enrollment  `json:"enrollments"`
23		Waivers       []*Waiver      `json:"waivers"`
24		NextResultSeq int            `json:"nextResultSeq"`
25	}
26	
27	// Load 从 path 读取记录。
28	//
29	// 文件不存在时返回空记录集，existed=false，且不报错——即“从空记录开始”。
30	// 文件存在但无法读取（权限、I/O 错误等）或内容损坏（非法 JSON、结构矛盾、
31	// 引用悬空等）时返回错误，调用方绝不应把该文件当作空记录覆盖写入。
32	// 空文件同样视为损坏，而不是空记录。
33	//
34	// 整份文件必须只含一条完整记录：记录前后允许空白（空格、制表符、换行、
35	// 回车），但完整记录结束后只要还有任何内容——多出的右花括号或右方括号、
36	// 拼接的第二段 JSON、普通文字或没写完的 JSON 片段——都判为损坏并拒绝读取，
37	// 绝不依据已读到的前半条记录继续办理业务。
38	//
39	// 同一个 JSON 对象内的字段名称也只能出现一次：无论重复的是学分、学生编号
40	// 还是其他字段，也无论两个值是否相同，整份文件都判为损坏。规则同时适用于
41	// 最外层对象与其中的每条记录，字段名以 JSON 解码后的文字比较（直接写出与
42	// Unicode 转义同名仍算重复）；限制只针对同一对象，不同记录各自携带同名字段
43	// 是正常结构，字符串值里提到字段名不算重复。
44	//
45	// 有效免修的依据校验与首次正常申请一致：任何状态为有效（approved）的免修，
46	// 其依据必须含有实际文字；依据为空，或全部由空白字符（空格、制表符、换行、
47	// 回车、全角空格 U+3000、不换行空格 U+00A0 等，允许混用）组成时，整份记录
48	// 按内容损坏拒绝读取，即使该要求另有通过修读也不例外。已拒绝申请的依据允许
49	// 为空或只有空白。检查只读不写：不会补填依据、不会改动免修状态，也不会修剪
50	// 含实际文字的依据中原有空白。
51	func Load(path string) (s *Store, existed bool, err error) {
52		f, err := os.Open(path)
53		if err != nil {
54			if errors.Is(err, os.ErrNotExist) {
55				return NewStore(), false, nil
56			}
57			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
58		}
59		defer f.Close()
60	
61		fi, err := f.Stat()
62		if err != nil {
63			return nil, false, fmt.Errorf("无法读取记录文件 %s 的信息：%w", path, err)
64		}
65		if fi.Size() == 0 {
66			return nil, true, fmt.Errorf("记录文件 %s 存在但为空，内容已损坏，未做任何修改", path)
67		}
68	
69		raw, err := io.ReadAll(f)
70		if err != nil {
71			return nil, false, fmt.Errorf("无法读取记录文件 %s：%w", path, err)
72		}
73	
74		// 先在 token 流上检查同一 JSON 对象内是否出现重复字段名。标准库直接
75		// 解进结构体时会用后一个重复键静默覆盖前一个（例如课程写了两个
76		// credit，4 会被 9 悄悄顶替），这样的记录无法明确说明字段归属，必须
77		// 整份判为损坏，绝不能据此核对或办理。仅扫描第一份完整值，其后内容
78		// 仍由下方的“完整记录之后不得有多余内容”检查处理。
79		var dupErr *duplicateFieldError
80		if err := scanDuplicateKeys(bytes.NewReader(raw)); errors.As(err, &dupErr) {
81			return nil, true, fmt.Errorf(
82				"记录文件 %s 内容损坏（同一 JSON 对象内字段 %q 重复出现，字段归属无法确定），未做任何修改",
83				path, dupErr.field)
84		}
85	
86		var data fileData
87		dec := json.NewDecoder(bytes.NewReader(raw))
88		dec.DisallowUnknownFields()
89		if err := dec.Decode(&data); err != nil {
90			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（JSON 解析失败：%v），未做任何修改", path, err)
91		}
92		// 完整记录之后必须只剩下空白：再解一条原始 JSON，仅 io.EOF 表示记录后
93		// 别无他物。不能用 dec.More() 判断——它只向前看“值起始”标记，记录后
94		// 多出的右花括号/右方括号会让 More() 直接返回 false 而被漏掉。再次
95		// Decode 能覆盖全部情形：成功读到值说明后面拼接了第二段 JSON；返回
96		// 语法错误或 unexpected EOF 说明尾部有孤立括号、普通文字或未写完的
97		// 片段。这些一律视为文件损坏。
98		var extra json.RawMessage
99		switch err := dec.Decode(&extra); {
100		case errors.Is(err, io.EOF):
101			// 唯一一份完整记录之后只有空白，符合格式。
102		case err == nil:
103			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后还拼接了其他 JSON 数据），未做任何修改", path)
104		default:
105			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（完整记录之后仍有无法解析的多余内容），未做任何修改", path)
106		}
107	
108		s = NewStore()
109		if err := s.loadData(&data); err != nil {
110			return nil, true, fmt.Errorf("记录文件 %s 内容损坏（%v），未做任何修改", path, err)
111		}
112		return s, true, nil
113	}
114	
115	// loadData 校验磁盘数据并重建索引；任何矛盾都作为损坏报错。
116	func (s *Store) loadData(d *fileData) error {
117		if d.Version != recordVersion {
118			return fmt.Errorf("不支持的记录版本 %d（当前支持版本 %d）", d.Version, recordVersion)
119		}
120	
121		// 课程
122		for _, c := range d.Courses {
123			if c == nil {
124				return errors.New("存在空的课程记录")
125			}
126			if c.ID == "" {
127				return errors.New("存在没有编号的课程")
128			}
129			if c.Name == "" {
130				return fmt.Errorf("课程 %s 没有名称", c.ID)
131			}
132			if c.Credit <= 0 {
133				return fmt.Errorf("课程 %s 学分不是正整数：%d", c.ID, c.Credit)
134			}
135			if _, dup := s.courseByID[c.ID]; dup {
136				return fmt.Errorf("课程编号 %s 重复", c.ID)
137			}
138			s.courses = append(s.courses, c)
139			s.courseByID[c.ID] = c
140		}
141	
142		// 学生
143		for _, st := range d.Students {
144			if st == nil || st.ID == "" {
145				return errors.New("存在没有编号的学生记录")
146			}
147			if _, dup := s.studentByID[st.ID]; dup {
148				return fmt.Errorf("学生编号 %s 重复", st.ID)
149			}
150			s.students = append(s.students, st)
151			s.studentByID[st.ID] = st
152		}
153	
154		// 要求
155		for _, r := range d.Requirements {
156			if r == nil {
157				return errors.New("存在空的课程要求记录")
158			}
159			if r.StudentID == "" || r.ID == "" {
160				return errors.New("存在缺少学生编号或要求编号的课程要求")
161			}
162			if _, ok := s.studentByID[r.StudentID]; !ok {
163				return fmt.Errorf("要求 %s 引用了不存在的学生 %s", r.ID, r.StudentID)
164			}
165			if _, ok := s.courseByID[r.CourseID]; !ok {
166				return fmt.Errorf("学生 %s 的要求 %s 引用了不存在的课程 %s",
167					r.StudentID, r.ID, r.CourseID)
168			}
169			key := reqKey(r.StudentID, r.ID)
170			if _, dup := s.reqByKey[key]; dup {
171				return fmt.Errorf("学生 %s 的要求编号 %s 重复", r.StudentID, r.ID)
172			}
173			dk := dupKey(r.StudentID, r.CourseID)
174			if other, dup := s.reqByDup[dk]; dup {
175				return fmt.Errorf("学生 %s 就课程 %s 存在重复要求 %s 与 %s",
176					r.StudentID, r.CourseID, other, r.ID)
177			}
178			s.requirements = append(s.requirements, r)
179			s.reqByKey[key] = r
180			s.reqByDup[dk] = r.ID
181		}
182	
183		// 修读
184		usedSeq := map[int]bool{}
185		for _, e := range d.Enrollments {
186			if e == nil {
187				return errors.New("存在空的修读记录")
188			}
189			if e.StudentID == "" || e.ID == "" {
190				return errors.New("存在缺少学生编号或修读编号的修读记录")
191			}
192			if _, ok := s.studentByID[e.StudentID]; !ok {
193				return fmt.Errorf("修读 %s 引用了不存在的学生 %s", e.ID, e.StudentID)
194			}
195			r := s.reqByKey[reqKey(e.StudentID, e.ReqID)]
196			if r == nil {
197				return fmt.Errorf("学生 %s 的修读 %s 引用了不存在的要求 %s",
198					e.StudentID, e.ID, e.ReqID)
199			}
200			if e.Term == "" {
201				return fmt.Errorf("学生 %s 的修读 %s 缺少学期", e.StudentID, e.ID)
202			}
203			switch e.Result {
204			case Enrolled, Passed, Failed:
205			default:
206				return fmt.Errorf("学生 %s 的修读 %s 含非法结果 %q", e.StudentID, e.ID, e.Result)
207			}
208			if e.Result == Enrolled {
209				if e.ResultSeq != 0 {
210					return fmt.Errorf("修读 %s 尚未提交结果却带有结果序号", e.ID)
211				}
212			} else {
213				if e.ResultSeq <= 0 {
214					return fmt.Errorf("修读 %s 已提交结果但缺少结果序号", e.ID)
215				}
216				if usedSeq[e.ResultSeq] {
217					return fmt.Errorf("结果提交序号 %d 重复，记录已损坏", e.ResultSeq)
218				}
219				usedSeq[e.ResultSeq] = true
220			}
221			key := reqKey(e.StudentID, e.ID)
222			if _, dup := s.enrByKey[key]; dup {
223				return fmt.Errorf("学生 %s 的修读编号 %s 重复", e.StudentID, e.ID)
224			}
225			s.enrollments = append(s.enrollments, e)
226			s.enrByKey[key] = e
227		}
228	
229		// 免修（被拒绝的申请允许指向当时不存在的要求、依据也可以为空；
230		// 已撤销的申请则必须保留一份曾经有效的申请所必需的信息）
231		approvedReq := map[ownerKey]string{} // (student, req) -> waiverID
232		for _, w := range d.Waivers {
233			if w == nil {
234				return errors.New("存在空的免修记录")
235			}
236			if w.StudentID == "" || w.ID == "" {
237				return errors.New("存在缺少学生编号或免修编号的免修记录")
238			}
239			if _, ok := s.studentByID[w.StudentID]; !ok {
240				return fmt.Errorf("免修 %s 引用了不存在的学生 %s", w.ID, w.StudentID)
241			}
242			switch w.Status {
243			case WaiverApproved, WaiverRejected, WaiverRevoked:
244			default:
245				return fmt.Errorf("学生 %s 的免修 %s 含非法状态 %q", w.StudentID, w.ID, w.Status)
246			}
247			switch w.Status {
248			case WaiverApproved:
249				// 有效免修的依据校验与首次正常申请完全一致：依据必须含有实际
250				// 文字，空串或全部由空白字符（空格、制表符、换行、全角空格
251				// U+3000、不换行空格 U+00A0 等，含混用）组成都按内容损坏
252				// 拒绝整份记录——这样的“有效免修”无法有据可查，即使该要求
253				// 另有通过修读也不能放过。检查只读不写，绝不修剪或改写文件
254				// 中已保存的依据原文，也不把它降级成已拒绝/已撤销。
255				if blankBasis(w.Basis) {
256					return fmt.Errorf("学生 %s 的有效免修 %s 缺少依据（依据为空或全部为空白字符）",
257						w.StudentID, w.ID)
258				}
259				rk := reqKey(w.StudentID, w.ReqID)
260				if s.reqByKey[rk] == nil {
261					return fmt.Errorf("有效免修 %s 指向的要求 %s 不存在或不属于该学生", w.ID, w.ReqID)
262				}
263				if other, dup := approvedReq[rk]; dup {
264					return fmt.Errorf("学生 %s 的要求 %s 同时存在有效免修 %s 与 %s",
265						w.StudentID, w.ReqID, other, w.ID)
266				}
267				approvedReq[rk] = w.ID
268			case WaiverRevoked:
269				// 撤销只取消免修对课程要求的满足作用，不能把缺少原依据、
270				// 失去要求归属的记录变成合法历史：目标要求必须真实存在于
271				// 该免修所属学生名下（同号要求只在其他学生名下不算），
272				// 原依据必须含有非空白内容（空白口径与有效免修一致，全角
273				// 空格、不换行空格等同样不算实际依据）。检查只读不写，
274				// 依据中有实际文字时原有空白一律保留，绝不为了通过检查
275				// 改写保存下来的材料内容。失效历史不参与有效免修的唯一
276				// 性限制。
277				if s.reqByKey[reqKey(w.StudentID, w.ReqID)] == nil {
278					return fmt.Errorf("学生 %s 的已撤销免修 %s 目标要求无效（要求 %s 不存在于该学生名下）",
279						w.StudentID, w.ID, w.ReqID)
280				}
281				if blankBasis(w.Basis) {
282					return fmt.Errorf("学生 %s 的已撤销免修 %s 原依据为空", w.StudentID, w.ID)
283				}
284			}
285			key := reqKey(w.StudentID, w.ID)
286			if _, dup := s.waiverByKey[key]; dup {
287				return fmt.Errorf("学生 %s 的免修编号 %s 重复", w.StudentID, w.ID)
288			}
289			s.waivers = append(s.waivers, w)
290			s.waiverByKey[key] = w
291		}
292	
293		if d.NextResultSeq < 0 {
294			return errors.New("结果提交序号计数器为负数")
295		}
296		for seq := range usedSeq {
297			if seq > d.NextResultSeq {
298				return fmt.Errorf("结果提交序号计数器 %d 小于已有序号 %d", d.NextResultSeq, seq)
299			}
300		}
301		s.nextResultSeq = d.NextResultSeq
302		return nil
303	}
304	
305	// Save 将全部记录原子写入 path：先写同目录临时文件，再重命名覆盖，
306	// 避免写到一半时损坏原文件。
307	func (s *Store) Save(path string) (err error) {
308		data := fileData{
309			Version:       recordVersion,
310			Courses:       s.courses,
311			Students:      s.students,
312			Requirements:  s.requirements,
313			Enrollments:   s.enrollments,
314			Waivers:       s.waivers,
315			NextResultSeq: s.nextResultSeq,
316		}
317		buf, err := json.MarshalIndent(&data, "", "  ")
318		if err != nil {
319			return fmt.Errorf("无法序列化记录：%w", err)
320		}
321		buf = append(buf, '\n')
322	
323		dir := filepath.Dir(path)
324		if dir == "" {
325			dir = "."
326		}
327		tmp, err := os.CreateTemp(dir, ".credit-*.tmp")
328		if err != nil {
329			return fmt.Errorf("无法在 %s 创建临时记录文件：%w", dir, err)
330		}
331		tmpName := tmp.Name()
332		defer func() {
333			if err != nil {
334				tmp.Close()
335				os.Remove(tmpName)
336			}
337		}()
338		if _, err = tmp.Write(buf); err != nil {
339			return fmt.Errorf("写入记录文件失败：%w", err)
340		}
341		if err = tmp.Sync(); err != nil {
342			return fmt.Errorf("写入记录文件失败：%w", err)
343		}
344		if err = tmp.Close(); err != nil {
345			return fmt.Errorf("写入记录文件失败：%w", err)
346		}
347		if err = os.Chmod(tmpName, 0o600); err != nil {
348			return fmt.Errorf("设置记录文件权限失败：%w", err)
349		}
350		if err = os.Rename(tmpName, path); err != nil {
351			return fmt.Errorf("保存记录文件 %s 失败：%w", path, err)
352		}
353		return nil
354	}
355

