290				w, action, err)
291		}
292		if w.Status != WaiverRejected || w.Reason != "免修依据为空" {
293			t.Fatalf("空白依据应按业务规则拒绝并保留原因，得到 %+v", w)
294		}
295	
296		dir := t.TempDir()
297		path := filepath.Join(dir, "records.json")
298		if err := s.Save(path); err != nil {
299			t.Fatalf("Save: %v", err)
300		}
301		reloaded, existed, err := Load(path)
302		if err != nil || !existed {
