func hex4(b []byte, i int) (rune, bool) {
    if i+4 > len(b) { return 0, false }
    var v rune
    for k := 0; k < 4; k++ {
        c := b[i+k]
        var d byte
        switch {
        case c >= '0' && c <= '9': d = c - '0'
        case c >= 'a' && c <= 'f': d = c - 'a' + 10
        case c >= 'A' && c <= 'F': d = c - 'A' + 10
        default: return 0, false
        }
        v = v*16 + rune(d)
    }
    return v, true
}
