		"两个高位代理项相连":      {`"id": "s1"`, `"id": "s` + hi + hi + `1"`},
		"高位代理项在字符串末尾":   {`"id": "s1"`, `"id": "s` + hi + `"`},
		"高位代理项后直接写普通字符": {`"id": "s1"`, `"id": "s` + hi + `x"`},
		"高位代理项后是普通字符转义": {`"id": "s1"`, `"id": "s` + hi + uesc("0041") + `"`},
		"课程名称含孤立高位代理项":  {`"name": "高等数学"`, `"name": "` + hi + `数学"`},
