	cont := string([]byte{0x80})             // 孤立延续字节
	overlong := string([]byte{0xC0, 0xAF})   // 过长编码
	surr := string([]byte{0xED, 0xA0, 0x80}) // 用 UTF-8 直接编码的代理项
	cases := map[string]struct{ old, rep string }{
