				`"reason": "免修依据为空"}]`},
	}
	for name, c := range cases {
		t.Run(name, func(t *testing.T) {
			content := replaceOnce(t, unicodeBaseRecord(), c.old, c.rep)
			path, raw := writeRawRecord(t, content)
			assertInvalidUnicode(t, path, raw)
		})
